rss.channel:
    {{ merchant_title }}
    {{ merchant_link }}
    {{ merchant_description }}
    {{ generated_at.strftime('%a, %d %b %Y %H:%M:%S GMT') }}
{% for product in products %}


      GY-{{ product.id }}
      {{ product.name }}
      {{ product_description(product) }}
      {{ product_url(product) }}
      {{ product_image_url(product) }}
      in_stock
      {% if product.unit == "Kg" and product.gramaj_list %}
      {% set merchant_grams = 1000 %}
        {{ '%.2f'|format(product.price * merchant_grams / 1000.0) }} TRY
        {{ merchant_grams }} g
        1 kg
      {% else %}
        {{ '%.2f'|format(product.price) }} TRY
      {% endif %}
      new
      {{ merchant_title }}
      {{ product.category }}
      no

{% endfor %}
